function onSuccess(data) {
  if (bootstrapped.value) return;
  bootstrapped.value = true;
  if (route.query.category || route.query.region || route.query.country) {
    if (route.query.category) { selectedCategories.value = [].concat(route.query.category); }
    if (route.query.country) { selectedCountries.value = [route.query.country]; }
    if (route.query.region) { const REGION_TO_COUNTRIES = { 'India': ['India'], 'Asia': ['Philippines','Indonesia','Myanmar','Pakistan','Singapore','Australia','Bangladesh','China','Sri Lanka','Thailand','Vietnam'], 'Middle East': ['Saudi Arabia','United Arab Emirates','Egypt','Qatar','Kuwait','Oman','Bahrain','Iraq','Jordan','Libya','Yemen'], 'Africa': ['Kenya','Tanzania','Congo, The Democratic Republic of the','Ghana','Mauritius','Nigeria','South Africa','Uganda'], 'Europe': ['Germany','France','Italy','Malta','Netherlands','Spain','Switzerland','United Kingdom'], 'Americas': ['United States','Canada'] }; let wizardRegions = []; try { wizardRegions = JSON.parse(route.query.region); } catch (e) { wizardRegions = [route.query.region]; } const mappedCountries = wizardRegions.flatMap(r => REGION_TO_COUNTRIES[r] || []); if (mappedCountries.length) { selectedCountries.value = mappedCountries; } }
  } else { try { const saved = JSON.parse(localStorage.getItem('connect_directory_filters') || 'null'); if (saved) { searchTerm.value = saved.searchTerm || ''; tierFilter.value = saved.tierFilter || ''; selectedCountries.value = saved.selectedCountries || []; selectedCategories.value = [...new Set(saved.selectedCategories || [])]; selectedApps.value = saved.selectedApps || []; } } catch (e) {} }
  try { mockLoggedIn.value = localStorage.getItem('connect_mock_logged_in') === '1'; } catch (e) {}
  try { localShortlist.value = JSON.parse(localStorage.getItem('connect_local_shortlist') || '[]'); } catch (e) { localShortlist.value = []; }
  const baseParams = { limit: 9, search: searchTerm.value, tier: tierFilter.value, country: JSON.stringify(selectedCountries.value), product: JSON.stringify(selectedApps.value), business_process: businessProcessFilter.value, implementation_type: implementationTypeFilter.value, language: languageFilter.value, min_rating: minRatingFilter.value, max_response_time: maxResponseTimeFilter.value }; const params = { ...baseParams, category: JSON.stringify(selectedCategories.value) }; directoryPartners.update({ params }); directoryPartners.reload().then(() => { const excludeNames = (directoryPartners.data || []).map(p => p.name); categoryFallback.update({ params: { ...baseParams, category: '', exclude: JSON.stringify(excludeNames) } }); categoryFallback.reload(); if ((selectedCountries.value || []).length) { countryFallback.update({ params: { ...params, country: '', exclude: JSON.stringify(excludeNames) } }); countryFallback.reload(); } }); filterFacets.update({ params }); filterFacets.reload();
}
